'use strict';
const APP_ID='year9-helpdesk-project',VERSION=1;
const teacher=new URLSearchParams(location.search).get('teacher')==='1';
const STORAGE=APP_ID+(teacher?'-teacher':'-student');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fields=new Map();
function reg(id,label,options){fields.set(id,{label,options});}
reg('name',UI.name);reg('className',UI.className);
STARTER.forEach(q=>reg(q.id,q.prompt,q.options?.map((_,i)=>String(i))));
for(const p of ['start','now'])for(const t of TOPICS){reg(`${p}_${t.id}`,t.check,['prior','support','gap','unattempted']);reg(`${p}_evidence_${t.id}`,B(t.title.en+' · evidence',t.title.ms+' · bukti',t.title.zh+' · 证据'));}
for(const t of TOPICS)reg('phase_'+t.id,t.check,[...PHASES.map(p=>p[0]),'unattempted']);
for(const p of ['start','end']){reg(p+'_focus',UI.focus,TOPICS.map(t=>t.id));reg(p+'_action',UI.action);}
reg('m1_predict',B('Predict: two people ahead, fifteen minutes available. What are the waiting and total times?','Ramal: dua orang di hadapan, lima belas minit tersedia. Apakah masa menunggu dan jumlah masa?','预测：前面有两人，可用时间为十五分钟。等待时间和总时间分别是多少？'));
reg('m1_explain',B('Explain why you converted the input to int and why your total includes Sam’s own help time.','Jelaskan sebab menukar input kepada int dan sebab jumlah merangkumi masa bantuan Sam sendiri.','解释为什么将输入转换为 int，以及为什么总时间包含帮助 Sam 本人所需的时间。'));
reg('advice_true',B('When the estimate fits, what should the user do?','Apabila anggaran muat, apakah tindakan pengguna?','估计时间足够时，用户应当做什么？'));
reg('advice_false',B('When the estimate does not fit, what should the user do?','Apabila anggaran tidak muat, apakah tindakan pengguna?','估计时间不足时，用户应当做什么？'));
reg('decision_reason',B('Explain why you used <= and why your outputs say “estimated”.','Jelaskan sebab menggunakan <= dan perkataan “anggaran” dalam output.','解释为什么使用 <=，以及输出为什么使用“估计”一词。'));
reg('peer',B('Partner feedback: name the line or test, explain the issue or confirmation, and record your next action.','Maklum balas rakan: nyatakan baris atau ujian, jelaskan isu atau pengesahan dan catat tindakan seterusnya.','同伴反馈：指出代码行或测试，说明问题或确认结果，并记录下一步。'));
for(const [id] of TESTS){reg('test_'+id+'_predict',B('Test '+id+' · prediction','Ujian '+id+' · ramalan','测试 '+id+' · 预测'));reg('test_'+id+'_explain',B('Test '+id+' · comparison and correction','Ujian '+id+' · perbandingan dan pembetulan','测试 '+id+' · 比较与修改'));}
const TERMS=[['input',B('Input','Input','输入')],['variable',B('Variable','Pemboleh ubah','变量')],['constant',B('Constant','Pemalar','常量')],['condition',B('Condition','Syarat','条件')],['output',B('Output','Output','输出')]];
for(const [id,label]of TERMS){reg('term_'+id,B(label.en+' · in my own words',label.ms+' · dengan kata sendiri',label.zh+' · 用自己的话解释'));reg('term_'+id+'_code',B(label.en+' · code evidence',label.ms+' · bukti kod',label.zh+' · 代码证据'));}
reg('buffer_predict',B('Predict what adding two buffer minutes changes in tests A, B and C.','Ramal perubahan apabila menambah dua minit penimbal dalam ujian A, B dan C.','预测增加两分钟缓冲时间会怎样改变测试 A、B 和 C。'));
reg('buffer_explain',B('Record the results for A, B and C. Explain the changed equality case and one limit of the estimate.','Catat hasil A, B dan C. Jelaskan perubahan kes sama tepat dan satu batasan anggaran.','记录 A、B 和 C 的结果。解释相等情况的变化，以及估计仍有的一项局限。'));
reg('guard_predict',B('Predict the advice for (-1, 15), (2, -1), (2, 15) and (4, 15).','Ramal nasihat bagi (-1, 15), (2, -1), (2, 15) dan (4, 15).','预测 (-1, 15)、(2, -1)、(2, 15) 和 (4, 15) 的建议。'));
reg('guard_explain',B('Record all four results. Explain why invalid numbers must not reach the calculations. What happens if someone types a word?','Catat keempat-empat hasil. Jelaskan sebab nombor tidak sah tidak boleh sampai ke pengiraan. Apakah berlaku jika seseorang menaip perkataan?','记录四种结果。解释为什么无效数字不能进入计算。如果用户输入一个词，会发生什么？'));
reg('exit_learning',B('What can you do now that you could not do at the start? Cite one code line or test.','Apakah yang boleh dilakukan sekarang berbanding permulaan? Nyatakan satu baris kod atau ujian.','现在你能做哪些开始时还不会做的事？指出一行代码或一次测试。'));
reg('exit_types',B('Explain the type returned by input(), the type after int(), and the True/False type produced by your comparison.','Jelaskan jenis daripada input(), jenis selepas int() dan jenis True/False daripada perbandingan.','解释 input() 返回的类型、int() 转换后的类型，以及比较得到的 True/False 所属类型。'));
reg('exit_constant',B('Name a constant and a variable in your code. Explain their different roles.','Namakan pemalar dan pemboleh ubah dalam kod. Jelaskan peranan yang berbeza.','指出代码中的一个常量和一个变量，解释它们不同的作用。'));
reg('exit_case',B('One person is ahead and eight minutes are available. Calculate the total and explain which branch runs.','Seorang di hadapan dan lapan minit tersedia. Kira jumlah dan jelaskan cabang yang berjalan.','前面有一人，可用时间为八分钟。计算总时间并解释执行哪个分支。'));
function fresh(){return {app:APP_ID,version:VERSION,page:0,lang:'en',mode:'focus',answers:{},checked:{},first:{},code:{},runs:{core:[],buffer:[],guard:[]},attached:{},updated:null};}
const programIds=['core','buffer','guard'];
function cleanRun(r){if(!r||typeof r!=='object'||typeof r.code!=='string'||r.code.length>20000||!['done','error','stopped','timeout'].includes(r.status))return null;return{id:String(r.id||'').slice(0,70),at:String(r.at||'').slice(0,40),code:r.code,output:String(r.output||'').slice(0,18000),error:String(r.error||'').slice(0,3000),status:r.status,predictions:Object.fromEntries(TESTS.map(([id])=>[id,typeof r.predictions?.[id]==='string'?r.predictions[id].slice(0,6000):''])),inputs:Array.isArray(r.inputs)?r.inputs.slice(0,40).filter(i=>i&&typeof i.value==='string').map(i=>({prompt:String(i.prompt||'').slice(0,1000),value:i.value.slice(0,500)})):[]};}
function validate(raw){if(!raw||raw.app!==APP_ID||raw.version!==VERSION)throw Error('Wrong lesson');const s=fresh();s.page=Number.isInteger(raw.page)&&raw.page>=0&&raw.page<8?raw.page:0;s.lang=['en','ms','zh'].includes(raw.lang)?raw.lang:'en';s.mode=raw.mode==='compare'?'compare':'focus';for(const[id,f]of fields){const v=raw.answers?.[id];if(typeof v==='string'&&v.length<=6000&&(!f.options||v===''||f.options.includes(v)))s.answers[id]=v;}for(const q of STARTER){if(raw.checked?.[q.id]===true)s.checked[q.id]=true;if(typeof raw.first?.[q.id]==='string')s.first[q.id]=raw.first[q.id].slice(0,6000);}for(const id of programIds){if(typeof raw.code?.[id]==='string'&&raw.code[id].length<=20000)s.code[id]=raw.code[id];if(Array.isArray(raw.runs?.[id]))s.runs[id]=raw.runs[id].slice(-30).map(cleanRun).filter(Boolean);}for(const[id]of TESTS){const r=cleanRun(raw.attached?.[id]);if(r)s.attached[id]=r;}s.updated=typeof raw.updated==='string'?raw.updated.slice(0,40):null;return s;}
let state=fresh(),storageOK=true,entry=!teacher,step=0,branch=false;
try{const data=localStorage.getItem(STORAGE);if(data)state=validate(JSON.parse(data));}catch{storageOK=false;}
let live=null;
const text=b=>typeof b==='string'?b:(b?.[state.lang]??b?.en??'');
function bi(b){if(typeof b==='string')return esc(b);return state.mode==='compare'&&state.lang!=='en'?`<span class="compare"><span lang="en">${esc(b.en)}</span><span class="translation" lang="${state.lang==='zh'?'zh-Hans':state.lang}">${esc(text(b))}</span></span>`:esc(text(b));}
const t=(en,ms,zh)=>bi(B(en,ms,zh));
const val=id=>state.answers[id]??'';
function save(){state.updated=new Date().toISOString();try{localStorage.setItem(STORAGE,JSON.stringify(state));storageOK=true;}catch{storageOK=false;}const el=document.getElementById('save-status');if(el)el.textContent=text(storageOK?UI.saved:UI.saveError)+(teacher?' · '+text(B('Teacher preview','Pratonton guru','教师预览')):'');}
function notice(b){document.getElementById('notice').textContent=text(b);clearTimeout(notice.timer);notice.timer=setTimeout(()=>document.getElementById('notice').textContent='',6500);}
function field(id,rows=3,label=fields.get(id)?.label){return `<label class="field" for="${id}"><span>${bi(label)}</span><textarea id="${id}" data-field="${id}" rows="${rows}" maxlength="6000">${esc(val(id))}</textarea></label>`;}
function select(id,options,label=fields.get(id)?.label){return `<label class="field" for="${id}"><span>${bi(label)}</span><select id="${id}" data-field="${id}"><option value="">${esc(text(UI.choose))}</option>${options.map(([v,l])=>`<option value="${v}" ${val(id)===v?'selected':''}>${esc(text(l))}</option>`).join('')}</select></label>`;}
const levelOptions=['prior','support','gap','unattempted'].map(k=>[k,UI[k]]);
const phaseOptions=[...PHASES.map(([k])=>[k,UI[k]]),['unattempted',UI.unattempted]];
const codeBlock=code=>`<pre class="code-block"><code>${esc(code)}</code></pre>`;
function panel(title,body,cls=''){return `<section class="panel ${cls}"><h2>${bi(title)}</h2>${body}</section>`;}
function steps(items){return `<ol class="step-list">${items.map(x=>`<li>${bi(x)}</li>`).join('')}</ol>`;}
function langControl(){return `<label>${bi(UI.language)} <select data-lang aria-label="${esc(text(UI.language))}">${[['en','English'],['ms','Bahasa Melayu'],['zh','简体中文']].map(([k,l])=>`<option value="${k}" ${state.lang===k?'selected':''}>${l}</option>`).join('')}</select></label>`;}
function hasWork(){return state.page>0||Object.entries(state.answers).some(([id,value])=>!['name','className'].includes(id)&&value.trim())||Object.keys(state.code).length>0||programIds.some(id=>state.runs[id].length>0);}
function welcome(){return `<main class="welcome" id="main"><div class="welcome-top"><div class="brand">CS with Mr Dave<br><span class="small">${t('Year 9 · Python project','Tahun 9 · Projek Python','九年级 · Python 项目')}</span></div>${langControl()}</div><div class="welcome-layout"><section><p class="eyebrow">${bi(C.subtitle)}</p><h1>${bi(C.title)}</h1><p class="lede">${bi(C.brief)}</p><div class="product-preview"><div class="preview-row"><span>01</span><div>${t('Ask for two numbers.','Minta dua nombor.','获取两个数字。')}</div></div><div class="preview-row"><span>02</span><div>${t('Calculate time and choose useful advice.','Kira masa dan pilih nasihat berguna.','计算时间并选择有用的建议。')}</div></div><div class="preview-row"><span>03</span><div>${t('Run it. Test both paths. Explain your choices.','Jalankan. Uji kedua-dua laluan. Jelaskan pilihan.','运行程序，测试两条路径，解释设计选择。')}</div></div></div></section><form class="welcome-form" id="entry-form"><p class="eyebrow">${t('Your learning notebook','Buku nota pembelajaran anda','你的学习记录')}</p><h2>${t('Ready to build?','Bersedia untuk membina?','准备开始编程了吗？')}</h2><label class="field" for="name"><span>${bi(UI.name)}</span><input id="name" data-field="name" maxlength="100" autocomplete="name" value="${esc(val('name'))}" required></label><label class="field" for="className"><span>${bi(UI.className)}</span><input id="className" data-field="className" maxlength="60" value="${esc(val('className'))}" required></label><div class="actions"><button class="primary" type="submit">${bi(UI.begin)}</button>${hasWork()?`<button type="button" data-action="resume">${bi(UI.resume)}</button>`:''}</div><p class="hint">${t('Your work stays in this browser. Save a backup to move devices.','Kerja kekal dalam pelayar ini. Simpan sandaran untuk menukar peranti.','作品保存在此浏览器。更换设备前请保存备份。')}</p><div class="band"><b>WAGBA</b><p>${bi(C.wagba)}</p></div><details><summary>${t('Already have a backup?','Sudah mempunyai sandaran?','已有备份？')}</summary>${restoreControl()}</details></form></div></main>`;}
function sidebar(){return `<aside class="sidebar"><div class="brand">${bi(C.title)}</div><p class="small">${t('Year 9 · 60 minutes · 2 main tasks','Tahun 9 · 60 minit · 2 tugasan utama','九年级 · 60 分钟 · 2 个主要任务')}</p><nav aria-label="${esc(text(B('Lesson stages','Peringkat pelajaran','课程阶段')))}">${C.nav.map((n,i)=>`<button data-page="${i}" ${i===state.page?'aria-current="step"':''}><span class="navnum">${String(i+1).padStart(2,'0')}</span><span>${bi(n)}</span></button>`).join('')}</nav><div class="aims"><div class="wagba"><b>WAGBA</b><p>${bi(C.wagba)}</p></div>${['knowledge','skills','understanding'].map(k=>`<div><b>${bi(UI[k])}</b><p>${bi(C[k])}</p></div>`).join('')}</div></aside>`;}
function head(){return `<div class="stage-meta"><span class="eyebrow">${bi(C.nav[state.page])}</span><span class="pill">${C.minutes[state.page]} ${t('minutes','minit','分钟')}</span></div><h1 tabindex="-1" id="page-title">${bi(C.pageTitles[state.page])}</h1>`;}
function render(){document.getElementById('skip-link').textContent=text(B('Skip to lesson','Langkau ke pelajaran','跳至课程'));document.documentElement.lang=state.lang==='zh'?'zh-Hans':state.lang;document.getElementById('app').innerHTML=entry?welcome():`<div class="shell">${sidebar()}<div><header class="topbar"><div><span class="student-id">${esc(val('name')||text(B('Teacher preview','Pratonton guru','教师预览')))}${val('className')?' · '+esc(val('className')):''}</span><div class="small" id="save-status">${esc(text(storageOK?UI.saved:UI.saveError))}${teacher?' · '+esc(text(B('Teacher preview: separate notebook','Pratonton guru: buku nota berasingan','教师预览：独立记录'))):''}</div></div><div class="toolbar">${langControl()}<label class="view-switch">${t('View','Paparan','视图')} <select data-mode aria-label="${esc(text(B('Reading view','Paparan bacaan','阅读视图')))}"><option value="focus" ${state.mode==='focus'?'selected':''}>${esc(text(B('Focus','Fokus','单语')))}</option><option value="compare" ${state.mode==='compare'?'selected':''}>${esc(text(B('Compare','Banding','双语对照')))}</option></select></label><button data-action="welcome">${bi(UI.welcome)}</button></div></header><main id="main">${head()}${[readPage,starterPage,()=>reflection(false),main1,main2,challenges,()=>reflection(true),plenary][state.page]()}<footer class="stepfooter"><button data-page="${state.page-1}" ${state.page===0?'disabled':''}>← ${bi(UI.previous)}</button>${state.page<7?`<button class="primary" data-page="${state.page+1}">${bi(UI.next)} →</button>`:`<span class="hint">${t('Keep a copy for next lesson.','Simpan salinan untuk pelajaran seterusnya.','保留一份副本供下节课使用。')}</span>`}</footer></main></div></div>`;bind();}
function go(page){if(page<0||page>7)return;if(live)finish('stopped');state.page=page;entry=false;save();render();document.getElementById('page-title')?.focus();window.scrollTo(0,0);}
function queue(){return `<div class="queue"><div class="person">${t('Ahead','Di hadapan','前面的人')}<span>4</span>${t('minutes','minit','分钟')}</div><div class="person">${t('Ahead','Di hadapan','前面的人')}<span>4</span>${t('minutes','minit','分钟')}</div><b>+</b><div class="person sam">Sam<span>4</span>${t('minutes','minit','分钟')}</div><b class="math">= 12</b></div>`;}
function tutor(){const rows=TUTOR_STEPS,active=rows[step];let memory={};rows.slice(0,step+1).forEach(r=>Object.assign(memory,r[1]));if(branch){if('people_ahead'in memory)memory.people_ahead='4';if('waiting_minutes'in memory)memory.waiting_minutes='16';if('total_minutes'in memory)memory.total_minutes='20';}const current=branch&&step===6?9:active[0];const code=TUTOR_CODE.replace('people_ahead = 2',branch?'people_ahead = 4':'people_ahead = 2');let note=active[2];if(branch&&step===1)note=B('Store 4 people ahead. The same program now receives a different starting value.','Simpan 4 orang di hadapan. Atur cara sama menerima nilai permulaan berbeza.','存储前面排队的 4 人。同一程序现在接收不同的起始值。');if(branch&&step===3)note=B('Calculate 4 × 4 = 16 minutes waiting.','Kira 4 × 4 = 16 minit menunggu.','计算 4 × 4 = 16 分钟等待时间。');if(branch&&step===4)note=B('Add Sam’s four minutes: 16 + 4 = 20 minutes total.','Tambah empat minit Sam: 16 + 4 = 20 minit jumlah.','加上 Sam 的四分钟：16 + 4 = 20 分钟总时间。');if(branch&&step===5)note=B('20 <= 15 is False. Skip the if output and choose the else branch.','20 <= 15 ialah False. Langkau output if dan pilih cabang else.','20 <= 15 为 False。跳过 if 的输出，选择 else 分支。');if(branch&&step===6)note=B('Print the second advice. Only the else branch runs in this case.','Cetak nasihat kedua. Hanya cabang else berjalan dalam kes ini.','显示第二条建议。此次只有 else 分支执行。');return `<div id="tutor"><div class="actions"><button data-action="case-fit" aria-pressed="${!branch}">${t('Case A: 2 people ahead','Kes A: 2 orang di hadapan','案例 A：前面有 2 人')}</button><button data-action="case-long" aria-pressed="${branch}">${t('Case B: 4 people ahead','Kes B: 4 orang di hadapan','案例 B：前面有 4 人')}</button></div><div class="grid"><ol class="code-lines">${code.split('\n').map((line,i)=>`<li class="${current===i+1?'active':''} ${step===6&&((branch&&i===6)||(!branch&&i===8))?'skip':''}" ${current===i+1?'aria-current="step"':''}>${esc(line)}</li>`).join('')}</ol><div><div class="tutor-note" role="status"><p class="eyebrow">${bi(UI.step)} ${step+1}/7 · ${bi(UI.line)} ${current}</p><p>${bi(note)}</p></div><div class="memory">${Object.entries(memory).map(([k,v])=>`<div><code>${k}</code><strong>${v}</strong></div>`).join('')}</div><div class="actions"><button data-action="tutor-back" ${step===0?'disabled':''}>${bi(UI.previous)}</button><button class="primary" data-action="tutor-next">${step===6?t('Replay','Ulang','重播'):bi(UI.next)}</button></div></div></div><div class="tablewrap"><table><thead><tr><th>${bi(UI.line)}</th><th>${t('What changed or happened','Perubahan atau peristiwa','改变或执行内容')}</th><th>${t('Value / result','Nilai / hasil','数值／结果')}</th></tr></thead><tbody>${rows.slice(0,step+1).map((r,i)=>{let key=Object.keys(r[1])[0]|| (i===5?'total_minutes <= minutes_available':'print');let value=key in memory?memory[key]:i===5?(branch?'False':'True'):(branch?'Arrange another time.':'Ask the helpdesk about being seen now.');return `<tr class="${i===step?'current-row':''}"><td>${branch&&i===6?9:r[0]}</td><td><code>${esc(key)}</code></td><td>${esc(value)}</td></tr>`;}).join('')}</tbody></table></div><p class="hint">${t('The highlight follows the executed line. A skipped branch is not executed. Your program will use input() instead of the given starting values.','Sorotan mengikuti baris yang dilaksanakan. Cabang dilangkau tidak dilaksanakan. Atur cara anda menggunakan input() menggantikan nilai permulaan diberi.','高亮跟随正在执行的代码行。跳过的分支不会执行。你的程序将用 input() 获取值，而不是预先给定数值。')}</p></div>`;}
function readPage(){return `<p class="lede">${bi(C.brief)}</p>`+panel(B('Your brief','Tugasan anda','你的任务'),`<p>${bi(C.finish)}</p><div class="flow"><div><b>${bi(UI.input)}</b>${t('People ahead + minutes available','Orang di hadapan + minit tersedia','前面人数 + 可用分钟数')}</div><div><b>${bi(UI.process)}</b>${t('Calculate waiting time and total time. Compare the total with the time available.','Kira masa menunggu dan jumlah masa. Bandingkan jumlah dengan masa tersedia.','计算等待时间和总时间，将总时间与可用时间比较。')}</div><div><b>${bi(UI.output)}</b>${t('Two estimates and one suitable advice path.','Dua anggaran dan satu laluan nasihat sesuai.','两项估计，以及一条合适的建议路径。')}</div></div><div class="band">${bi(C.assumption)}</div>`)+panel(B('The total includes Sam','Jumlah termasuk Sam','总时间包含 Sam'),queue()+`<p>${t('Two people ahead take 8 minutes. Add 4 minutes for Sam: 12 minutes in total. With 15 minutes available, the estimate fits. With 4 people ahead, the total is 20, so the advice changes.','Dua orang di hadapan mengambil 8 minit. Tambah 4 minit untuk Sam: jumlah 12 minit. Dengan 15 minit tersedia, anggaran muat. Dengan 4 orang di hadapan, jumlah ialah 20, jadi nasihat berubah.','前面两人需要 8 分钟，再加上 Sam 的 4 分钟，总共 12 分钟。可用 15 分钟时，估计时间足够。如果前面有 4 人，总时间为 20 分钟，建议就会改变。')}</p>`,'teaching')+panel(B('Follow the program, one line at a time','Ikuti atur cara, satu baris pada satu masa','逐行跟随程序'),tutor(),'teaching')+panel(B('Before the starter: input returns text','Sebelum permulaan: input mengembalikan teks','练习前：input 返回文本'),codeBlock('people_text = input("People ahead: ")\npeople_ahead = int(people_text)')+`<p>${t('If you type 2, the first line receives "2" (str). The second line converts it to 2 (int). The comparison 12 <= 15 produces True (bool). = assigns a value; <= compares two values.','Jika anda menaip 2, baris pertama menerima "2" (str). Baris kedua menukarkannya kepada 2 (int). Perbandingan 12 <= 15 menghasilkan True (bool). = memberikan nilai; <= membandingkan dua nilai.','如果输入 2，第一行接收 "2"（str）。第二行将其转换为 2（int）。比较 12 <= 15 得到 True（bool）。= 用于赋值；<= 用于比较两个值。')}</p>`);}
function starterPage(){return `<p class="lede">${t('Use what you have just read. Keep your first attempt, then use the feedback to find a useful focus. You can continue with unfinished answers.','Gunakan bacaan tadi. Kekalkan percubaan pertama, kemudian gunakan maklum balas untuk memilih fokus. Anda boleh teruskan walaupun jawapan belum siap.','运用刚读到的内容。保留第一次尝试，再根据反馈选择学习重点。未完成的答案不会阻止继续学习。')}</p>`+panel(B('Six starting checks','Enam semakan awal','六项起点检查'),STARTER.map((q,i)=>`<section class="question"><p class="eyebrow">${i+1} · ${bi(UI[TOPICS.find(x=>x.id===q.topic).area])}</p>${q.options?`<fieldset style="border:0;padding:0"><legend>${bi(q.prompt)}</legend>${q.code?codeBlock(q.code):''}<div class="options">${q.options.map((o,n)=>`<label class="option"><input type="radio" name="${q.id}" data-field="${q.id}" value="${n}" ${val(q.id)===String(n)?'checked':''}><span>${q.id==='q3'?`<code style="white-space:pre-wrap">${esc(o)}</code>`:bi(o)}</span></label>`).join('')}</div></fieldset>`:`${q.code?codeBlock(q.code):''}${field(q.id)}`}<button data-check="${q.id}">${q.options?bi(UI.check):bi(UI.model)}</button><div id="feedback-${q.id}">${feedback(q)}</div></section>`).join(''));}
function feedback(q){if(!state.checked[q.id])return '';return `<div class="feedback">${q.options?`<strong>${val(q.id)===''?t('Not attempted yet.','Belum dicuba.','尚未尝试。'):val(q.id)===String(q.answer)?t('This matches the rule.','Ini sepadan dengan peraturan.','这符合规则。'):t('Revisit this idea.','Semak semula idea ini.','重新检查这个概念。')}</strong>`:''}<p>${bi(q.why)}</p>${!q.options?`<p class="hint">${t('Compare the reasoning with your own words. This is guidance, not an automatic mark.','Bandingkan sebab dengan kata anda sendiri. Ini panduan, bukan markah automatik.','用自己的话对照推理。这是指导，不是自动评分。')}</p>`:''}</div>`;}
function development(prefix){return ['knowledge','skills','understanding'].map(area=>{const topics=TOPICS.filter(x=>x.area===area),counts={prior:0,support:0,gap:0,unattempted:0,blank:0};topics.forEach(x=>counts[val(prefix+'_'+x.id)||'blank']++);return{area,...counts,need:counts.support+counts.gap};});}
function developmentSummary(prefix){const data=development(prefix),highest=Math.max(...data.map(d=>d.need)),leaders=data.filter(d=>d.need===highest),pending=data.reduce((n,d)=>n+d.blank+d.unattempted,0);return `<div class="countgrid">${data.map(d=>`<div class="countcard"><b>${bi(UI[d.area])}</b><strong>${d.prior}/2 ${t('independent','berdikari','独立展示')}</strong><div>${t('With support','Dengan sokongan','借助支持')}: ${d.support}/2</div><div>${t('Still developing','Masih dipelajari','仍在发展')}: ${d.gap}/2</div><div class="small">${t('Unattempted / unselected','Belum dicuba / dipilih','未尝试／未选择')}: ${d.unattempted+d.blank}/2</div></div>`).join('')}</div><div class="band">${highest?`${t('The highest development count points to','Bilangan keperluan tertinggi menunjukkan','当前发展需求最多的领域是')} <b>${leaders.map(d=>bi(UI[d.area])).join(', ')}</b> (${highest}/2). ${t('This counts checks needing support or further learning. Choose one of those checks and a useful action below.','Ini mengira semakan yang memerlukan sokongan atau pembelajaran lanjut. Pilih satu semakan dan tindakan berguna di bawah.','这统计了需要支持或继续学习的检查项。请在下方选择一个具体检查项和有效行动。')}`:pending?t('Complete the checks you attempted before choosing a focus. Unattempted work is not wrong.','Lengkapkan semakan yang dicuba sebelum memilih fokus. Kerja belum dicuba bukan salah.','先评价已尝试的检查项，再选择重点。未尝试不等于错误。'):t('You have demonstrated all six checks independently. Apply your learning with less support or choose a further challenge.','Anda menunjukkan keenam-enam semakan secara berdikari. Gunakan pembelajaran dengan kurang sokongan atau pilih cabaran lanjutan.','你已独立展示全部六项。请减少支持来应用所学，或选择进阶挑战。')}${highest?`<p>${leaders.map(d=>bi(AREA_ACTIONS[d.area])).join(' ')}</p>`:''}${pending?`<p class="hint">${pending} ${t('checks remain unattempted or unselected; this suggestion is provisional.','semakan belum dicuba atau dipilih; cadangan ini sementara.','项尚未尝试或选择，此建议仍是暂时的。')}</p>`:''}</div>`;}
function phaseSummary(){const counts=Object.fromEntries(PHASES.map(([id])=>[id,0]));let pending=0;TOPICS.forEach(x=>{const phase=val('phase_'+x.id);if(phase in counts)counts[phase]++;else pending++;});const total=6-pending,max=Math.max(...Object.values(counts)),leaders=Object.keys(counts).filter(k=>counts[k]===max),helps=TOPICS.filter(x=>val('phase_'+x.id)==='drowning');return `<div class="phases">${PHASES.map(([id,description])=>`<div><h3>${bi(UI[id])} · ${counts[id]}/${total||6}</h3><p>${bi(description)}</p></div>`).join('')}</div><div class="band">${total?`${max>total/2?t('Your majority phase','Fasa majoriti anda','你的多数学习阶段'):leaders.length>1?t('Your tied highest phases','Fasa tertinggi yang seri','并列最多的学习阶段'):t('Your most selected phase','Fasa paling banyak dipilih','选择最多的学习阶段')}: <b>${leaders.map(k=>bi(UI[k])).join(', ')}</b> (${max}/${total}). ${leaders.length>1?t('Choose the area where your next action will help most.','Pilih bidang yang paling mendapat manfaat daripada tindakan seterusnya.','选择下一步行动最能帮助你的领域。'):bi(PHASES.find(([id])=>id===leaders[0])[1])}`:t('Select a phase for each area you attempted. These describe your learning experience, not your ability level.','Pilih fasa bagi setiap bidang yang dicuba. Ini menerangkan pengalaman pembelajaran, bukan tahap kebolehan.','为每个已尝试的领域选择阶段。这描述学习体验，而非能力等级。')}${pending?`<p class="hint">${pending} ${t('checks unattempted or unselected. The summary is provisional.','semakan belum dicuba atau dipilih. Rumusan ini sementara.','项未尝试或未选择，汇总仍是暂时的。')}</p>`:''}</div>${helps.length?`<div class="band warning"><b>${t('Help still matters here','Bantuan masih diperlukan di sini','这些方面仍需要帮助')}</b><p>${helps.map(x=>bi(x.title)).join(', ')}. ${t('Show your teacher or partner the specific line or question. This reflection does not send an alert.','Tunjukkan baris atau soalan tertentu kepada guru atau rakan. Refleksi ini tidak menghantar makluman.','请向老师或同伴指出具体代码行或问题。此反思不会发送求助通知。')}</p></div>`:''}`;}
function reflection(end){const p=end?'now':'start';return `<p class="lede">${end?t('Use your program and tests as evidence. What you can demonstrate and how difficult the learning feels are two separate judgements.','Gunakan atur cara dan ujian sebagai bukti. Kebolehan yang ditunjukkan dan kesukaran pembelajaran ialah dua pertimbangan berasingan.','用程序和测试作为证据。能展示什么与学习体验有多难，是两个独立的判断。'):t('Look back at your starter answers. A correct choice is a clue; writing and explaining your own code is stronger evidence. Recognise what you already know, then choose what to improve.','Lihat semula jawapan permulaan. Pilihan betul ialah petunjuk; menulis dan menjelaskan kod sendiri ialah bukti lebih kukuh. Kenal pasti pengetahuan sedia ada, kemudian pilih perkara untuk diperbaiki.','回顾练习答案。选对答案提供线索；自己编写并解释代码是更有力的证据。认可已有知识，再选择改进方向。')}</p>`+panel(end?B('Your evidence now','Bukti anda kini','你现在的证据'):B('Your six starting checks','Enam semakan permulaan anda','你的六项起点检查'),`<div id="development-summary">${developmentSummary(p)}</div><div class="checks">${TOPICS.map((topic,i)=>`<article class="check"><p class="eyebrow">${bi(UI[topic.area])} · ${i+1}</p><h3>${bi(topic.title)}</h3><p>${bi(topic.check)}</p><p class="hint">${bi(topic.evidence)}</p>${end?`<p class="small">${t('Earlier','Sebelum ini','之前')}: <b>${val('start_'+topic.id)?bi(UI[val('start_'+topic.id)]):bi(UI.noEvidence)}</b>${val('start_evidence_'+topic.id)?' · '+esc(val('start_evidence_'+topic.id)):''}</p>`:`<details><summary>${t('Look at my starter evidence','Lihat bukti permulaan saya','查看我的起点证据')}</summary><p>${esc(val('q'+(i+1))===''?text(UI.noEvidence):STARTER[i].options?text(STARTER[i].options[Number(val('q'+(i+1)))]):val('q'+(i+1)))}</p></details>`}${select(p+'_'+topic.id,levelOptions,end?UI.current:B('My starting point','Titik permulaan saya','我的起点'))}${end?select('phase_'+topic.id,phaseOptions,UI.phase):''}${field(p+'_evidence_'+topic.id,2,UI.evidence)}</article>`).join('')}</div>`)+(end?panel(B('Your learning phase summary','Rumusan fasa pembelajaran anda','学习阶段汇总'),`<div id="phase-summary">${phaseSummary()}</div>`):'')+panel(B('Choose a specific next step','Pilih langkah seterusnya yang khusus','选择具体的下一步'),select((end?'end':'start')+'_focus',TOPICS.map(x=>[x.id,x.title]))+field((end?'end':'start')+'_action',3)+`<p class="hint">${t('Knowledge: clarify a meaning. Skills: practise the code, then try without the example. Understanding: explain a choice and apply it to a different case.','Pengetahuan: jelaskan maksud. Kemahiran: latih kod, kemudian cuba tanpa contoh. Pemahaman: jelaskan pilihan dan gunakannya pada kes berbeza.','知识：弄清含义。技能：练习代码，再不看示例尝试。理解：解释选择，并应用到不同情况。')}</p>`);}
function programCode(id){return state.code[id]??(id==='core'?text(CORE_SCAFFOLD):text(B('# Copy your core program with the button above, then improve it.\n','# Salin atur cara utama dengan butang di atas, kemudian perbaikinya.\n','# 使用上方按钮复制主程序，然后改进它。\n')));}
function lastRun(id){return state.runs[id].at(-1);}
function runHint(r){if(!r||!r.error)return '';let hint=/ValueError|invalid literal/i.test(r.error)?B('int() needs whole-number text such as 2. A word or 2.5 cannot be converted with this input rule. Try valid input, then explain this limitation.','int() memerlukan teks nombor bulat seperti 2. Perkataan atau 2.5 tidak boleh ditukar dengan peraturan input ini. Cuba input sah dan jelaskan batasan ini.','int() 需要像 2 这样的整数文本。单词或 2.5 无法按此规则转换。先尝试有效输入，再解释这一局限。'):/NameError/i.test(r.error)?B('Check the spelling of the named variable and assign it before using it. Python distinguishes uppercase and lowercase.','Semak ejaan pemboleh ubah dan berikan nilai sebelum menggunakannya. Python membezakan huruf besar dan kecil.','检查变量拼写，并在使用前赋值。Python 区分大小写。'):/SyntaxError|IndentationError|bad input/i.test(r.error)?B('Read the error line. Check colons, brackets, quotation marks and four-space indentation after if/else.','Baca baris ralat. Semak titik bertindih, kurungan, tanda petik dan inden empat ruang selepas if/else.','查看报错行。检查冒号、括号、引号，以及 if/else 后的四空格缩进。'):B('Read the Python message and check the named line. Use Stop if your code repeats unexpectedly.','Baca mesej Python dan semak baris dinyatakan. Gunakan Hentikan jika kod mengulang tanpa dijangka.','阅读 Python 消息并检查所指出的代码行。若代码意外重复，可点击停止。');return `<div class="error-help">${bi(hint)}</div>`;}
function consoleHTML(id){const r=live?.program===id?live.run:lastRun(id);const waiting=live?.program===id&&live.pending;return `<div class="console-status" role="status">${bi(r?UI[waiting?'waiting':live?.program===id?'running':r.status]:UI.ready)}</div><pre class="console-output" aria-label="${esc(text(UI.output))}" tabindex="0">${r?esc(r.output+(r.error?'\n'+r.error:'')):esc(text(UI.emptyConsole))}</pre>${waiting?`<form class="input-request" data-input-form="${id}"><label for="python-input-${id}">${esc(waiting.prompt||text(B('Enter input:','Masukkan input:','请输入：')))}</label><input id="python-input-${id}" name="response" maxlength="500" autocomplete="off" autocapitalize="off" spellcheck="false"><button class="primary" type="submit">${bi(UI.send)}</button><p class="hint">${t('Send an empty response with Enter if you want to test it. Stop cancels the run.','Hantar jawapan kosong dengan Enter jika mahu mengujinya. Hentikan membatalkan larian.','如需测试空输入，可直接按 Enter。停止按钮会取消运行。')}</p></form>`:''}${runHint(r)}${r&&r.code!==programCode(id)?`<p class="stale">${bi(UI.stale)}</p>`:''}`;}
function ide(id){const value=programCode(id);return `<section class="ide" id="ide-${id}" aria-label="${esc(text(UI.editor))}"><div class="ide-top"><h3>${bi(UI.editor)} · ${id==='core'?'helpdesk.py':id+'.py'}</h3><div class="actions"><button class="primary" data-run="${id}" ${live?'disabled':''}>▶ ${bi(UI.run)}</button><button data-stop="${id}" ${live?.program===id?'':'disabled'}>${bi(UI.stop)}</button><button data-download-code="${id}">${bi(UI.download)}</button></div></div><div class="ide-body"><div class="editor-side"><label class="editor-label" for="code-${id}">${t('Your code · Tab inserts 4 spaces · Ctrl/⌘ + Enter runs','Kod anda · Tab memasukkan 4 ruang · Ctrl/⌘ + Enter menjalankan','你的代码 · Tab 插入 4 个空格 · Ctrl/⌘ + Enter 运行')}</label><div class="editor-wrap"><pre class="line-numbers" aria-hidden="true">${value.split('\n').map((_,i)=>i+1).join('\n')}</pre><textarea id="code-${id}" class="code-input" data-code="${id}" aria-label="${esc(text(UI.editor))} ${id}" rows="15" maxlength="20000" spellcheck="false" autocomplete="off" autocapitalize="off" autocorrect="off" wrap="off">${esc(value)}</textarea></div></div><div class="console" id="console-${id}">${consoleHTML(id)}</div></div><div class="ide-bottom">${id==='core'&&state.page===4?`<p><a href="#test-cards">${t('Go to predictions and test records','Pergi ke ramalan dan rekod ujian','前往预测与测试记录')}</a></p>`:''}${t('Enter one response for each console question. Stop cancels a run; your code stays saved.','Masukkan satu jawapan bagi setiap soalan konsol. Hentikan membatalkan larian; kod anda kekal disimpan.','为每个控制台问题输入一个回答。停止会取消运行，代码仍会保存。')}</div><div class="history" id="history-${id}">${historyHTML(id)}</div></section>`;}
function historyHTML(id){return state.runs[id].length?`<details><summary>${bi(UI.history)} (${state.runs[id].length})</summary><p class="hint">${t('The latest 30 runs are retained for each editor. Recorded core tests stay in the test table.','30 larian terkini disimpan bagi setiap editor. Ujian utama yang direkod kekal dalam jadual ujian.','每个编辑器保留最近 30 次运行。已记录的主程序测试会保留在测试表中。')}</p>${state.runs[id].slice().reverse().map(r=>`<div class="run-entry"><b>${esc(r.at.slice(11,19))} · ${bi(UI[r.status])}</b><p class="small">${bi(UI.input)}: ${esc(r.inputs.map(i=>JSON.stringify(i.value)).join(', ')||'—')}</p><pre>${esc(r.output+(r.error?'\n'+r.error:''))}</pre><details><summary>${bi(UI.codeUsed)}</summary>${codeBlock(r.code)}</details></div>`).join('')}</details>`:'';}
function main1(){return `<p class="lede">${t('Build the first half of your program. It should ask the user, calculate both times and print clear results. Add the decision in Main Task 2.','Bina bahagian pertama atur cara. Ia perlu bertanya pengguna, mengira kedua-dua masa dan mencetak hasil jelas. Tambah keputusan dalam Tugasan Utama 2.','先完成程序的前半部分：向用户提问、计算两种时间并清晰输出。主要任务 2 再添加判断。')}</p>`+panel(B('1. Read input, then convert it','1. Baca input, kemudian tukarkannya','1. 读取输入，再转换'),codeBlock('people_text = input("People ahead: ")\npeople_ahead = int(people_text)')+`<p>${t('A compact version combines those steps:','Versi ringkas menggabungkan langkah itu:','紧凑写法将这两步合并：')}</p>`+codeBlock('people_ahead = int(input("People ahead: "))')+`<div class="tablewrap"><table><thead><tr><th>${t('Part','Bahagian','部分')}</th><th>${bi(UI.meaning)}</th></tr></thead><tbody><tr><td><code>input("People ahead: ")</code></td><td>${t('Ask the question; receive text such as "2".','Tanya soalan; terima teks seperti "2".','提出问题；接收如 "2" 的文本。')}</td></tr><tr><td><code>int(...)</code></td><td>${t('Convert suitable whole-number text into an integer.','Tukar teks nombor bulat yang sesuai kepada integer.','把合适的整数文本转换为整数。')}</td></tr><tr><td><code>people_ahead =</code></td><td>${t('Store the result using a meaningful name.','Simpan hasil dengan nama bermakna.','使用有意义的名称存储结果。')}</td></tr></tbody></table></div>`,'teaching')+panel(B('2. Use names that explain the job','2. Gunakan nama yang menjelaskan tugas','2. 用名称说明用途'),`<div class="tablewrap"><table><thead><tr><th>${t('Avoid','Elakkan','避免')}</th><th>${t('Use instead','Gunakan','改用')}</th><th>${t('Why','Sebab','原因')}</th></tr></thead><tbody><tr><td><code>2people = 2</code></td><td><code>people_ahead = 2</code></td><td>${t('A Python name cannot start with a digit.','Nama Python tidak boleh bermula dengan digit.','Python 名称不能以数字开头。')}</td></tr><tr><td><code>x = 12</code></td><td><code>total_minutes = 12</code></td><td>${t('The purpose and units are visible.','Tujuan dan unit jelas.','用途和单位一目了然。')}</td></tr><tr><td><code>time = 4</code></td><td><code>MINUTES_PER_PERSON = 4</code></td><td>${t('Uppercase signals the intended constant. Python can still reassign it.','Huruf besar menandakan pemalar yang dimaksudkan. Python masih boleh memberikan nilai baharu.','大写表示预定常量，但 Python 仍允许重新赋值。')}</td></tr></tbody></table></div>`,'teaching')+panel(B('3. Study a worked example','3. Kaji contoh lengkap','3. 学习一个完整示例'),`<p>${t('This example uses 3 minutes per person. Your task uses 4. Read each calculation before writing your own version.','Contoh ini menggunakan 3 minit seorang. Tugasan anda menggunakan 4. Baca setiap pengiraan sebelum menulis versi sendiri.','此示例使用每人 3 分钟。你的任务使用 4 分钟。先阅读每一步计算，再编写自己的版本。')}</p>`+codeBlock(MODEL_INPUT)+`<div class="band">${t('With 2 people ahead: 2 × 3 = 6 minutes waiting; 6 + 3 = 9 minutes including your own help. Print the stored numbers without quotation marks around their variable names.','Dengan 2 orang di hadapan: 2 × 3 = 6 minit menunggu; 6 + 3 = 9 minit termasuk bantuan sendiri. Cetak nombor tersimpan tanpa tanda petik pada nama pemboleh ubah.','前面有 2 人时：2 × 3 = 6 分钟等待；6 + 3 = 9 分钟包含自己的服务时间。打印变量值时，不要给变量名加引号。')}</div>`,'teaching')+panel(B('Your build: collect and calculate','Binaan anda: kumpul dan kira','你的程序：获取与计算'),steps([B('Set MINUTES_PER_PERSON to 4. Ask for people_ahead and minutes_available; convert each input to int.','Tetapkan MINUTES_PER_PERSON kepada 4. Minta people_ahead dan minutes_available; tukar setiap input kepada int.','将 MINUTES_PER_PERSON 设为 4。获取 people_ahead 和 minutes_available，并分别转换为 int。'),B('Calculate waiting_minutes, then total_minutes including your own help. Print both estimates with labels and minutes.','Kira waiting_minutes, kemudian total_minutes termasuk bantuan sendiri. Cetak kedua-dua anggaran dengan label dan minit.','计算 waiting_minutes，再计算包含本人服务时间的 total_minutes。输出两项估计，并写清标签和分钟单位。'),B('Predict the result below. Run the program and enter 2, then 15, when asked. Compare the output with your prediction.','Ramal hasil di bawah. Jalankan atur cara dan masukkan 2, kemudian 15 apabila ditanya. Bandingkan output dengan ramalan.','先在下方预测。运行程序，按提示依次输入 2 和 15。将输出与预测比较。')])+field('m1_predict')+ide('core')+field('m1_explain')+`<p class="hint">${t('This first prototype expects non-negative whole numbers. int() does not check whether a negative value makes sense. You can improve this in the challenges.','Prototaip pertama menjangka nombor bulat bukan negatif. int() tidak menyemak sama ada nilai negatif munasabah. Anda boleh memperbaikinya dalam cabaran.','此原型先接受非负整数。int() 不会检查负数是否合理。进阶挑战中可以改进这一点。')}</p>`);}
function matchingRun(id){const test=TESTS.find(x=>x[0]===id);return state.runs.core.slice().reverse().find(r=>r.status==='done'&&r.code===programCode('core')&&r.inputs.length===2&&r.inputs.every((x,i)=>/^\+?\d+$/.test(x.value.trim())&&Number(x.value)===test[i+1]));}
function testsHTML(){return TESTS.map(([id,people,minutes,title])=>{const r=state.attached[id];return `<article class="panel"><h3>${t('Test','Ujian','测试')} ${id} · ${bi(title)}</h3><p><code>people_ahead = ${people}</code> · <code>minutes_available = ${minutes}</code></p>${field('test_'+id+'_predict',2,B('Before running: predict the waiting time, total, True/False result and advice.','Sebelum menjalankan: ramal masa menunggu, jumlah, hasil True/False dan nasihat.','运行前：预测等待时间、总时间、True/False 结果及建议。'))}<div class="actions"><a href="#ide-core">${t('Back to the Python editor','Kembali ke editor Python','返回 Python 编辑器')}</a><button data-attach="${id}" ${matchingRun(id)?'':'disabled'}>${bi(UI.attach)}</button><span class="small">${matchingRun(id)?t('A matching run of this code is ready.','Larian kod sepadan tersedia.','当前代码已有匹配的运行。'):bi(UI.noRun)}</span></div>${r?`<div class="feedback"><b>${bi(UI.actual)} · ${esc(r.inputs.map(x=>x.value).join(', '))}</b><p><b>${t('Prediction saved when this run began','Ramalan disimpan ketika larian bermula','此次运行开始时保存的预测')}:</b> ${esc(r.predictions?.[id]||text(UI.noEvidence))}</p><pre>${esc(r.output)}</pre>${r.code!==programCode('core')?`<p class="stale">${bi(UI.stale)}</p>`:''}<p class="hint">${t('This records what ran, not an automatic correctness mark. Check both the calculation and the advice.','Ini merekod larian, bukan markah ketepatan automatik. Semak pengiraan dan nasihat.','这记录运行事实，并不自动判定正确。请检查计算和建议。')}</p><details><summary>${bi(UI.codeUsed)}</summary>${codeBlock(r.code)}</details></div>`:`<p class="empty">${bi(UI.noEvidence)}</p>`}${field('test_'+id+'_explain',2,UI.testExplain)}</article>`;}).join('');}
function main2(){return `<p class="lede">${t('Continue the same program from Main Task 1. First add the decision; then work with a partner to test and improve it.','Sambung atur cara yang sama daripada Tugasan Utama 1. Tambah keputusan dahulu; kemudian uji dan perbaiki bersama rakan.','继续主要任务 1 的同一个程序。先添加判断，再与同伴测试并改进。')}</p>`+panel(B('A. Study a complete decision','A. Kaji keputusan lengkap','A. 学习完整判断'),codeBlock(MODEL_DECISION)+`<div class="tablewrap"><table><thead><tr><th>${t('Condition','Syarat','条件')}</th><th>${t('Meaning','Maksud','含义')}</th><th>${t('Executed branch','Cabang dilaksanakan','执行的分支')}</th></tr></thead><tbody><tr><td><code>9 <= 12 → True</code></td><td>${t('The estimate fits.','Anggaran muat.','估计时间足够。')}</td><td><code>if</code></td></tr><tr><td><code>18 <= 12 → False</code></td><td>${t('The estimate is too long.','Anggaran terlalu lama.','估计时间过长。')}</td><td><code>else</code></td></tr><tr><td><code>12 <= 12 → True</code></td><td>${t('Equality is included. With < it would be False.','Kesamaan termasuk. Dengan <, hasilnya False.','包含相等情况；若使用 <，则为 False。')}</td><td><code>if</code></td></tr></tbody></table></div><p>${t('A colon starts each branch. Indent its statements by four spaces. Only one branch runs. Two unconditional print statements do not create two decision paths.','Titik bertindih memulakan setiap cabang. Inden pernyataannya dengan empat ruang. Hanya satu cabang berjalan. Dua pernyataan print tanpa syarat tidak membentuk dua laluan keputusan.','冒号开始分支，分支语句缩进四个空格。每次只执行一个分支。两个无条件的 print 并不构成两条判断路径。')}</p>`,'teaching')+panel(B('B. Plan helpful advice','B. Rancang nasihat berguna','B. 规划有用的建议'),`<div class="grid"><div>${field('advice_true',3)}<p class="hint">${t('Explain that the estimate fits and ask whether the helpdesk can see the user now.','Jelaskan anggaran muat dan minta pengguna bertanya sama ada meja bantuan boleh membantu sekarang.','说明估计时间足够，并建议询问服务台现在是否能提供帮助。')}</p></div><div>${field('advice_false',3)}<p class="hint">${t('Explain that it is too long. Suggest arranging another time and asking the teacher how to continue.','Jelaskan masa terlalu lama. Cadangkan masa lain dan bertanya guru cara meneruskan kerja.','说明估计时间过长，建议另约时间并询问老师如何继续学习。')}</p></div></div><div class="band">${t('Both outputs should give an action. Neither should guarantee a fix.','Kedua-dua output perlu memberi tindakan. Tiada satu pun patut menjamin pembaikan.','两种输出都应给出行动建议，都不应保证问题一定解决。')}</div>`)+panel(B('C. Add the decision to your program','C. Tambah keputusan pada atur cara','C. 为程序添加判断'),steps([B('Use your calculated total_minutes in the comparison. Do not replace the inputs with fixed values.','Gunakan total_minutes yang dikira dalam perbandingan. Jangan gantikan input dengan nilai tetap.','使用计算得到的 total_minutes 进行比较。不要用固定值替代输入。'),B('Write if/else and the two different advice outputs. Keep the calculated time outputs.','Tulis if/else dan dua output nasihat berbeza. Kekalkan output masa dikira.','编写 if/else 和两种不同的建议，同时保留计算时间的输出。'),B('Before each run, make a prediction in the test card below. Then Run Python, type the two inputs, and record the matching completed run.','Sebelum setiap larian, buat ramalan dalam kad ujian di bawah. Kemudian jalankan Python, taip dua input dan rekod larian selesai yang sepadan.','每次运行前，先在下方测试卡中写预测。再运行 Python、输入两个值，并记录匹配的完整运行。')])+ide('core')+field('decision_reason'))+panel(B('D. Partner walkthrough and three tests','D. Jejak bersama rakan dan tiga ujian','D. 同伴逐行检查与三次测试'),steps([B('The author chooses A, B or C and explains the predicted values and advice. The partner points to each executed code line.','Penulis memilih A, B atau C dan menjelaskan ramalan nilai serta nasihat. Rakan menunjuk setiap baris kod yang dilaksanakan.','作者选择 A、B 或 C，解释预测的数值和建议。同伴指出每一行执行的代码。'),B('Follow input → conversion → calculation → condition → chosen output. Explain which branch is skipped.','Ikuti input → penukaran → pengiraan → syarat → output dipilih. Jelaskan cabang yang dilangkau.','依次跟随输入、转换、计算、条件和所选输出，并解释跳过哪个分支。'),B('Run all three tests. Give feedback naming a line or test. Correct and rerun, or explain why the result already meets the rule.','Jalankan ketiga-tiga ujian. Beri maklum balas dengan menyatakan baris atau ujian. Betulkan dan jalankan semula, atau jelaskan sebab hasil memenuhi peraturan.','运行全部三项测试。反馈时指出具体代码行或测试。修改并重跑，或解释原结果为什么符合规则。')])+`<details><summary>${t('Revisit the highlighted trace tutor','Lihat semula tutor jejak bersorot','重看高亮追踪示例')}</summary>${tutor()}</details><div id="test-cards">${testsHTML()}</div>${field('peer')}`);}
function challenges(){return `<p class="lede">${t('When your core program works, use extra time to improve it. Choose a level that moves your learning forward. Your challenge code is separate from your core program.','Apabila atur cara utama berfungsi, gunakan masa tambahan untuk memperbaikinya. Pilih tahap yang memajukan pembelajaran. Kod cabaran berasingan daripada atur cara utama.','主程序能运行后，用剩余时间改进它。选择能帮助你进步的级别。挑战代码与主程序分开保存。')}</p>`+panel(B('Level 1 · Explain your code','Tahap 1 · Jelaskan kod anda','第 1 级 · 解释代码'),`<p>${t('Use your own words and point to a line from the program you wrote. Explain its job for Sam.','Gunakan kata sendiri dan nyatakan baris daripada atur cara anda. Jelaskan tugasnya untuk Sam.','用自己的话解释，并指出自己程序中的一行代码，说明它如何帮助 Sam。')}</p><div class="tablewrap"><table><thead><tr><th>${t('Word','Istilah','词汇')}</th><th>${t('My explanation','Penjelasan saya','我的解释')}</th><th>${t('A line from my program','Baris daripada atur cara saya','程序中的一行')}</th></tr></thead><tbody>${TERMS.map(([id,label])=>`<tr><th>${bi(label)}</th><td>${field('term_'+id,2)}</td><td>${field('term_'+id+'_code',2)}</td></tr>`).join('')}</tbody></table></div>`)+panel(B('Level 2 · Allow a little extra time','Tahap 2 · Berikan sedikit masa tambahan','第 2 级 · 预留额外时间'),`<p>${t('Real help can take longer than expected. Add a two-minute buffer to the total, then compare this adjusted total with the available time.','Bantuan sebenar boleh mengambil masa lebih lama. Tambah penimbal dua minit kepada jumlah, kemudian bandingkan jumlah terlaras dengan masa tersedia.','实际帮助可能比预计更久。给总时间增加两分钟缓冲，再将调整后的总时间与可用时间比较。')}</p>`+codeBlock('BUFFER_MINUTES = 2\nadjusted_total = total_minutes + BUFFER_MINUTES')+steps([B('Copy your core program. Add the buffer calculation after total_minutes has a value.','Salin atur cara utama. Tambah pengiraan penimbal selepas total_minutes mempunyai nilai.','复制主程序。在 total_minutes 已赋值后添加缓冲计算。'),B('Print the adjusted estimate and use it in the condition. Keep both advice paths.','Cetak anggaran terlaras dan gunakannya dalam syarat. Kekalkan kedua-dua laluan nasihat.','输出调整后的估计，并用它作条件判断。保留两条建议路径。'),B('Predict and run A (2,15), B (4,15) and C (2,12). Explain why C changes.','Ramal dan jalankan A (2,15), B (4,15) dan C (2,12). Jelaskan perubahan C.','预测并运行 A (2,15)、B (4,15)、C (2,12)。解释 C 为什么改变。')])+field('buffer_predict')+`<button data-copy-core="buffer">${bi(UI.copyCore)}</button>`+ide('buffer')+field('buffer_explain'))+panel(B('Level 3 · Catch an invalid number','Tahap 3 · Kesan nombor tidak sah','第 3 级 · 检测无效数字'),`<p>${t('A negative queue length or available time does not make sense. Check both inputs before calculating. The example below checks a different value.','Panjang baris gilir atau masa tersedia negatif tidak munasabah. Semak kedua-dua input sebelum mengira. Contoh di bawah menyemak nilai berbeza.','负的排队人数或可用时间没有意义。计算前检查两个输入。下面的示例检查另一个值。')}</p>`+codeBlock('tickets = int(input("Tickets: "))\nif tickets < 0:\n    print("Enter zero or a positive whole number.")\nelse:\n    print("The number can be used.")')+`<div class="band">${t('Your guard condition: people_ahead < 0 or minutes_available < 0. or is True if either condition is True. Put calculations and the original if/else inside the guard’s else block, with another level of indentation.','Syarat semakan anda: people_ahead < 0 or minutes_available < 0. or ialah True jika salah satu syarat True. Letakkan pengiraan dan if/else asal dalam blok else semakan, dengan satu lagi tahap inden.','检查条件：people_ahead < 0 or minutes_available < 0。任一条件为 True，or 就为 True。将计算和原来的 if/else 放在输入检查的 else 内，并增加一级缩进。')}</div><p>${t('Test (-1,15), (2,-1), (2,15) and (4,15). Invalid inputs should get a correction request, with no estimate. Typing a word still needs a separate conversion-handling feature.','Uji (-1,15), (2,-1), (2,15) dan (4,15). Input tidak sah perlu mendapat permintaan pembetulan tanpa anggaran. Menaip perkataan masih memerlukan ciri pengendalian penukaran berasingan.','测试 (-1,15)、(2,-1)、(2,15)、(4,15)。无效输入应收到修改提示，不能输出估计。输入单词仍需要另加转换错误处理。')}</p>`+field('guard_predict')+`<button data-copy-core="guard">${bi(UI.copyCore)}</button>`+ide('guard')+field('guard_explain'));}
function restoreControl(){return `<label class="upload">${bi(UI.restore)}<input type="file" data-restore accept="application/json,.json"></label>`;}
function plenary(){return `<p class="lede">${t('Explain your learning using your own code and tests. Then save a copy you can continue next lesson.','Jelaskan pembelajaran menggunakan kod dan ujian sendiri. Kemudian simpan salinan untuk disambung pada pelajaran seterusnya.','用自己的代码和测试解释所学，再保存一份下节课可继续使用的作品。')}</p>`+panel(B('Your final explanation','Penjelasan akhir anda','最后的解释'),['exit_learning','exit_types','exit_constant','exit_case'].map(id=>field(id,2)).join(''))+panel(B('Save, check, submit','Simpan, semak, hantar','保存、检查、提交'),steps([B('Check your name and class. Save your work as PDF; choose Save as PDF in the print window.','Semak nama dan kelas. Simpan kerja sebagai PDF; pilih Save as PDF dalam tetingkap cetak.','检查姓名和班级。点击保存为 PDF，在打印窗口选择另存为 PDF。'),B('Open the saved PDF and check that your code and tests appear. Download your .py file so you can continue programming.','Buka PDF disimpan dan semak kod serta ujian. Muat turun fail .py untuk meneruskan pengaturcaraan.','打开已保存的 PDF，确认包含代码和测试。下载 .py 文件以便继续编程。'),B('Upload the PDF and .py file to this lesson’s Teams assignment, then select Hand in / Turn in.','Muat naik PDF dan fail .py ke tugasan Teams pelajaran ini, kemudian pilih Hand in / Turn in.','将 PDF 和 .py 文件上传到本课 Teams 作业，然后点击提交。')])+`<div class="actions"><button class="primary" data-action="pdf">${bi(UI.savePDF)}</button><button data-download-code="core">${bi(UI.download)}</button></div><p class="hint">${t('You can save partial work. This app does not upload to Teams.','Anda boleh menyimpan kerja belum lengkap. Aplikasi ini tidak memuat naik ke Teams.','未完成的作品也可以保存。此应用不会自动上传到 Teams。')}</p><details><summary>${t('Backup and other saving options','Sandaran dan pilihan simpanan lain','备份和其他保存方式')}</summary><p>${t('Full backup restores editable work in this lesson. Readable report opens a copy in a browser. A backup downloads before a restore replaces your current notebook.','Sandaran penuh memulihkan kerja boleh edit dalam pelajaran ini. Laporan boleh dibaca membuka salinan dalam pelayar. Sandaran dimuat turun sebelum pemulihan menggantikan buku nota semasa.','完整备份可恢复本课中可编辑的作品。可阅读报告能在浏览器中打开。恢复替换当前记录前会下载当前备份。')}</p><div class="actions"><button data-action="backup">${bi(UI.backup)}</button><button data-action="html">${bi(UI.readable)}</button></div>${restoreControl()}</details>`);}
function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),15000);}
function backup(){save();download('Year9-Helpdesk-Backup.json',JSON.stringify(state,null,2),'application/json');}
function reportAnswers(ids){return ids.filter(id=>val(id).trim()).map(id=>{let answer=val(id);const q=STARTER.find(q=>q.id===id);if(q?.options)answer=text(q.options[Number(answer)]);else if(/^(start|now|phase)_[kus]\d$/.test(id))answer=text(UI[answer]);else if(id.endsWith('_focus'))answer=text(TOPICS.find(x=>x.id===answer)?.title||answer);let html=`<h3>${bi(fields.get(id).label)}</h3><p>${esc(answer).replace(/\n/g,'<br>')}</p>`;if(id in state.first&&state.first[id]!==val(id)){const first=q?.options?text(q.options[Number(state.first[id])]):state.first[id];html+=`<p><i>${t('First answer before feedback','Jawapan pertama sebelum maklum balas','查看反馈前的首次答案')}: ${esc(first)}</i></p>`;}return html;}).join('');}
function report(){const savedMode=state.mode;state.mode='focus';let out=`<article class="report-content"><h1>${bi(C.title)}</h1><p>${esc(val('name'))} · ${esc(val('className'))}</p><p><b>WAGBA:</b> ${bi(C.wagba)}</p><p>${t('Recorded answers and runs. Unattempted activities are omitted.','Jawapan dan larian direkodkan. Aktiviti belum dicuba tidak disertakan.','记录的答案和运行。未尝试的活动不列入。')}</p>`;
 if(Object.hasOwn(state.code,'core')||state.runs.core.length)out+=`<h2>${t('My helpdesk program','Atur cara meja bantuan saya','我的服务台程序')}</h2>${codeBlock(programCode('core'))}`;
 const mainAnswers=['m1_predict','m1_explain','advice_true','advice_false','decision_reason','peer'];if(mainAnswers.some(id=>val(id).trim()))out+=`<h2>${t('My plan and explanation','Rancangan dan penjelasan saya','我的计划与解释')}</h2>${reportAnswers(mainAnswers)}`;
 for(const[id]of TESTS){const r=state.attached[id];const ids=['test_'+id+'_predict','test_'+id+'_explain'];if(!r&&!ids.some(k=>val(k).trim()))continue;out+=`<h2>${t('Test','Ujian','测试')} ${id}</h2>${reportAnswers(ids)}`;if(r)out+=`<p><b>${t('Prediction saved when the run began','Ramalan ketika larian bermula','运行开始时保存的预测')}:</b> ${esc(r.predictions?.[id]||text(UI.noEvidence))}</p><p>${bi(UI.input)}: ${esc(r.inputs.map(x=>x.value).join(', '))}</p><pre>${esc(r.output)}</pre>${r.code!==programCode('core')?`<p>${bi(UI.stale)}</p><p>${bi(UI.codeUsed)}</p>${codeBlock(r.code)}`:''}`;}
 const attachedIds=new Set(Object.values(state.attached).map(r=>r.id));const extra=state.runs.core.filter(r=>!attachedIds.has(r.id));if(extra.length){out+=`<h2>${t('Other core-program runs','Larian atur cara utama lain','其他主程序运行')}</h2>`;for(const r of extra)out+=runReport(r,'core');}
 if(STARTER.some(q=>val(q.id).trim()))out+=`<h2>${bi(C.nav[1])}</h2>${reportAnswers(STARTER.map(q=>q.id))}`;
 if(TOPICS.some(x=>val('start_'+x.id))||val('start_action')){out+=`<h2>${bi(C.nav[2])}</h2>${developmentSummary('start')}`;for(const x of TOPICS)if(val('start_'+x.id)||val('start_evidence_'+x.id))out+=`<h3>${bi(x.title)}</h3><p>${val('start_'+x.id)?bi(UI[val('start_'+x.id)]):bi(UI.noEvidence)}</p><p>${esc(val('start_evidence_'+x.id))}</p>`;out+=reportAnswers(['start_focus','start_action']);}
 const termIds=TERMS.flatMap(([id])=>['term_'+id,'term_'+id+'_code']);if(termIds.some(id=>val(id).trim()))out+=`<h2>${t('Challenge 1: explain my code','Cabaran 1: jelaskan kod saya','挑战 1：解释我的代码')}</h2>${reportAnswers(termIds)}`;
 for(const id of ['buffer','guard']){if(!Object.hasOwn(state.code,id)&&!state.runs[id].length&&!val(id+'_predict')&&!val(id+'_explain'))continue;out+=`<h2>${id==='buffer'?t('Buffer challenge','Cabaran penimbal','缓冲挑战'):t('Input guard challenge','Cabaran semakan input','输入检查挑战')}</h2>`;if(Object.hasOwn(state.code,id))out+=codeBlock(programCode(id));out+=reportAnswers([id+'_predict',id+'_explain']);for(const r of state.runs[id])out+=runReport(r,id);}
 if(TOPICS.some(x=>val('now_'+x.id)||val('phase_'+x.id))||val('end_action')){out+=`<h2>${bi(C.nav[6])}</h2>${developmentSummary('now')}${phaseSummary()}`;for(const x of TOPICS)if(val('now_'+x.id)||val('phase_'+x.id)||val('now_evidence_'+x.id))out+=`<h3>${bi(x.title)}</h3><p>${bi(UI.current)}: ${val('now_'+x.id)?bi(UI[val('now_'+x.id)]):bi(UI.noEvidence)}</p><p>${bi(UI.phase)}: ${val('phase_'+x.id)?bi(UI[val('phase_'+x.id)]):bi(UI.noEvidence)}</p><p>${esc(val('now_evidence_'+x.id))}</p>`;out+=reportAnswers(['end_focus','end_action']);}
 const exit=['exit_learning','exit_types','exit_constant','exit_case'];if(exit.some(id=>val(id).trim()))out+=`<h2>${bi(C.nav[7])}</h2>${reportAnswers(exit)}`;
 out+='</article>';state.mode=savedMode;return out;}
function runReport(r,id){return `<h3>${bi(UI[r.status])} · ${esc(r.at)}</h3><p>${bi(UI.input)}: ${esc(r.inputs.map(x=>JSON.stringify(x.value)).join(', ')||'—')}</p><pre>${esc(r.output+(r.error?'\n'+r.error:''))}</pre>${r.code!==programCode(id)?`<p>${bi(UI.codeUsed)}</p>${codeBlock(r.code)}`:''}`;}
function printPDF(){if(live)finish('stopped');save();document.getElementById('print-report').innerHTML=report();window.print();}
function readable(){download('Year9-Helpdesk-Report.html',`<!doctype html><html lang="${state.lang}"><meta charset="utf-8"><title>${esc(text(C.title))}</title><style>body{max-width:960px;margin:2rem auto;padding:1rem;font:16px/1.5 Arial;color:#18261d}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#f1f4ed;padding:1rem}h2{margin-top:2rem}.countgrid,.phases{display:flex;gap:1rem;flex-wrap:wrap}.countcard,.phases>div{border:1px solid #bbb;padding:1rem}.countcard strong{display:block}.band{background:#f1f4ed;padding:1rem}p{overflow-wrap:anywhere}</style>${report()}</html>`,'text/html');}
function refreshConsole(id,focusInput=false){const el=document.getElementById('console-'+id);if(el){el.innerHTML=consoleHTML(id);const out=el.querySelector('.console-output');if(out)out.scrollTop=out.scrollHeight;if(focusInput)el.querySelector('input')?.focus();}document.querySelectorAll('[data-code]').forEach(el=>el.readOnly=Boolean(live));document.querySelectorAll('[data-run]').forEach(b=>b.disabled=Boolean(live));document.querySelectorAll('[data-stop]').forEach(b=>b.disabled=live?.program!==b.dataset.stop);const history=document.getElementById('history-'+id);if(history&&!live)history.innerHTML=historyHTML(id);}
function armTimer(){if(!live)return;clearTimeout(live.timer);live.timer=setTimeout(()=>finish('timeout',text(B('Execution took too long. Check for a loop that never ends.','Pelaksanaan terlalu lama. Semak gelung yang tidak tamat.','执行时间过长。请检查是否存在无限循环。'))),6000);}
function finish(status,error=''){if(!live)return;const job=live;live=null;clearTimeout(job.timer);job.worker?.terminate();job.run.status=status;job.run.error=error;state.runs[job.program].push(job.run);state.runs[job.program]=state.runs[job.program].slice(-30);save();refreshConsole(job.program);updateTests();}
function startRun(id){if(live||!programIds.includes(id))return;const code=programCode(id);if(!code.trim()){notice(B('Write some Python first.','Tulis Python dahulu.','请先编写 Python。'));return;}state.code[id]=code;save();const run={id:Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,8),at:new Date().toISOString(),code,output:'',inputs:[],predictions:Object.fromEntries(TESTS.map(([id])=>[id,val('test_'+id+'_predict')])),status:'running',error:''};live={program:id,run,worker:null,pending:null,timer:null};try{const worker=new Worker('python-worker.js?v=1');live.worker=worker;worker.onmessage=({data})=>{if(!live||live.worker!==worker)return;if(data.type==='output'){live.run.output=(live.run.output+String(data.text)).slice(0,18000);refreshConsole(id);}else if(data.type==='input'){clearTimeout(live.timer);live.pending={id:data.id,prompt:String(data.prompt).slice(0,1000)};refreshConsole(id,true);}else if(data.type==='done')finish('done');else if(data.type==='error')finish('error',String(data.error));};worker.onerror=()=>finish('error',text(B('Python could not load. Open the lesson using its HTTP/HTTPS link and check that the vendor files are present.','Python tidak dapat dimuatkan. Buka pelajaran melalui pautan HTTP/HTTPS dan semak fail vendor tersedia.','Python 无法加载。请通过 HTTP/HTTPS 链接打开课程，并确认附带的运行文件存在。')));armTimer();worker.postMessage({type:'run',code});refreshConsole(id);}catch{finish('error',text(B('This browser could not start the Python worker. Use the lesson web link.','Pelayar ini tidak dapat memulakan worker Python. Gunakan pautan web pelajaran.','此浏览器无法启动 Python 工作线程。请使用课程网页链接。')));}}
function sendInput(form){if(!live?.pending||live.program!==form.dataset.inputForm)return;if(live.run.inputs.length>=40){finish('error',text(B('Input limit reached. Check whether a question repeats.','Had input dicapai. Semak sama ada soalan berulang.','达到输入次数限制。请检查问题是否重复。')));return;}const value=form.elements.response.value.slice(0,500),p=live.pending;live.run.inputs.push({prompt:p.prompt,value});live.run.output=(live.run.output+p.prompt+value+'\n').slice(0,18000);live.pending=null;const id=live.program;live.worker.postMessage({type:'input',id:p.id,value});armTimer();refreshConsole(id);}
function updateTests(){const el=document.getElementById('test-cards');if(el)el.innerHTML=testsHTML();}
function bind(){document.querySelectorAll('[data-code]').forEach(el=>{const gutter=el.previousElementSibling;el.addEventListener('scroll',()=>gutter.scrollTop=el.scrollTop);el.addEventListener('keydown',ev=>{if(ev.key==='Tab'){ev.preventDefault();const start=el.selectionStart,end=el.selectionEnd;if(el.value.length+4>20000)return;el.setRangeText('    ',start,end,'end');el.dispatchEvent(new Event('input',{bubbles:true}));}else if(ev.key==='Enter'&&(ev.ctrlKey||ev.metaKey)){ev.preventDefault();startRun(el.dataset.code);}else if(ev.key==='Enter'&&!ev.shiftKey){const pos=el.selectionStart,line=el.value.slice(0,pos).split('\n').at(-1),indent=(line.match(/^ */)||[''])[0]+(line.trimEnd().endsWith(':')?'    ':'');if(el.value.length+indent.length+1<=20000){ev.preventDefault();el.setRangeText('\n'+indent,el.selectionStart,el.selectionEnd,'end');el.dispatchEvent(new Event('input',{bubbles:true}));}}});});}
document.addEventListener('input',ev=>{const el=ev.target;if(el.dataset.field&&fields.has(el.dataset.field)){state.answers[el.dataset.field]=el.value.slice(0,6000);delete state.checked[el.dataset.field];const fb=document.getElementById('feedback-'+el.dataset.field);if(fb)fb.innerHTML='';save();if(/^(start_|now_|phase_)/.test(el.dataset.field)){const summary=document.getElementById('development-summary');if(summary)summary.innerHTML=developmentSummary(state.page===6?'now':'start');const phases=document.getElementById('phase-summary');if(phases)phases.innerHTML=phaseSummary();}}else if(el.dataset.code){state.code[el.dataset.code]=el.value.slice(0,20000);el.previousElementSibling.textContent=el.value.split('\n').map((_,i)=>i+1).join('\n');save();refreshConsole(el.dataset.code);updateTests();}});
document.addEventListener('submit',ev=>{const form=ev.target;if(form.id==='entry-form'){ev.preventDefault();go(0);}else if(form.dataset.inputForm){ev.preventDefault();sendInput(form);}});
document.addEventListener('change',async ev=>{const el=ev.target;if(el.hasAttribute('data-lang')||el.hasAttribute('data-mode')){if(live)finish('stopped');if(el.hasAttribute('data-lang'))state.lang=el.value;else state.mode=el.value;save();render();}else if(el.hasAttribute('data-restore')){const file=el.files[0];if(!file)return;try{if(file.size>8000000)throw Error('Too large');const restored=validate(JSON.parse(await file.text()));if(live)finish('stopped');backup();state=restored;save();render();notice(B('Backup restored. Your previous notebook was downloaded first.','Sandaran dipulihkan. Buku nota sebelumnya dimuat turun dahulu.','备份已恢复。之前的记录已先下载保存。'));}catch{notice(B('This is not a valid backup for this lesson. Your work has not been replaced.','Ini bukan sandaran sah bagi pelajaran ini. Kerja anda tidak diganti.','这不是本课的有效备份。你的作品未被替换。'));}}});
document.addEventListener('click',ev=>{const b=ev.target.closest('button');if(!b||b.disabled)return;if(b.dataset.page!==undefined){go(Number(b.dataset.page));return;}if(b.dataset.run){startRun(b.dataset.run);return;}if(b.dataset.stop){finish('stopped');return;}if(b.dataset.downloadCode){download(b.dataset.downloadCode==='core'?'helpdesk.py':b.dataset.downloadCode+'.py',programCode(b.dataset.downloadCode),'text/x-python');return;}if(b.dataset.check){const q=STARTER.find(q=>q.id===b.dataset.check);if(!q)return;if(val(q.id).trim()&&!Object.hasOwn(state.first,q.id))state.first[q.id]=val(q.id);state.checked[q.id]=true;save();document.getElementById('feedback-'+q.id).innerHTML=feedback(q);return;}if(b.dataset.attach){const r=matchingRun(b.dataset.attach);if(r){state.attached[b.dataset.attach]=JSON.parse(JSON.stringify(r));save();updateTests();notice(B('Run recorded. Now compare it with your prediction.','Larian direkodkan. Kini bandingkan dengan ramalan.','运行已记录。现在请与预测比较。'));}return;}if(b.dataset.copyCore){const id=b.dataset.copyCore;if(Object.hasOwn(state.code,id)&&state.code[id].trim()&&!confirm(text(B('Replace this challenge code with your current core program? Existing run history stays available.','Gantikan kod cabaran ini dengan atur cara utama semasa? Sejarah larian kekal tersedia.','用当前主程序替换此挑战代码？原运行历史会保留。'))))return;if(live)finish('stopped');state.code[id]=programCode('core');save();render();document.getElementById('ide-'+id)?.scrollIntoView({block:'center'});return;}const action=b.dataset.action;if(action==='welcome'){if(live)finish('stopped');entry=true;render();window.scrollTo(0,0);}else if(action==='resume'){const f=document.getElementById('entry-form');if(f.reportValidity())go(state.page);}else if(action==='pdf')printPDF();else if(action==='backup')backup();else if(action==='html')readable();else if(action?.startsWith('tutor-')||action?.startsWith('case-')){if(action==='tutor-back')step=Math.max(0,step-1);if(action==='tutor-next')step=step===6?0:step+1;if(action==='case-fit'){branch=false;step=0;}if(action==='case-long'){branch=true;step=0;}const target=document.getElementById('tutor');if(target)target.outerHTML=tutor();}});
window.addEventListener('pagehide',()=>{if(live)finish('stopped');save();});
render();
